/* ------------------------------------------------------------------ */
/* Classification + assembly                                            */
/* ------------------------------------------------------------------ */

function nameWeightHint(family: string): number | undefined {
  const n = family.toLowerCase();
  if (/\b(black|heavy)\b/.test(n)) return 8;
  if (/\bbold\b/.test(n)) return 6;
  if (/\b(light|thin|hairline)\b/.test(n)) return 2;
  return undefined;
}

function deriveClassification(
  family: string,
  category: FontCategory,
  condensed: boolean,
  expanded: boolean,
  tagLabelsLower: string,
): FontClassification {
  const cl: FontClassification = {};
  if (category === "Serif") cl.serif = true;
  if (category === "Sans-Serif") cl.sans = true;
  if (category === "Monospace") cl.monospace = true;
  if (category === "Display") cl.display = true;
  if (category === "Script") {
    cl.script = true;
    cl.connected = true;
  }
  if (tagLabelsLower.includes("monospace")) cl.monospace = true;
  if (tagLabelsLower.includes("/script/")) {
    cl.script = true;
    cl.connected = true;
  }
  if (/geometric|superellipse/.test(tagLabelsLower)) cl.geometric = true;
  if (/humanist|venetian|old style|garalde/.test(tagLabelsLower)) cl.humanist = true;
  if (condensed) cl.condensed = true;
  if (expanded) cl.wide = true;
  if (/rounded|blobby/.test(tagLabelsLower)) cl.rounded = true;
  if (
    /didone|fat face|scotch|transitional|high contrast|black|clarendon|slab/.test(
      tagLabelsLower,
    )
  ) {
    cl.highContrast = true;
  }
  if (/old style|garalde|humanist|easy reading/.test(tagLabelsLower)) {
    cl.lowContrast = true;
  }
  if (/neo grotesque|grotesque|techno|stencil|pixel|futuristic/.test(tagLabelsLower)) {
    cl.angular = true;
  }
  if (/brush|handwritten|informal/.test(tagLabelsLower)) cl.script = true;
  const hint = nameWeightHint(family);
  cl.weightHint = hint ?? 4;
  return cl;
}

function tagLabel(path: string): string {
  const parts = path.split("/").filter(Boolean);
  return parts.slice(1).join(" ") || parts[0] || path;
}

function buildGoogleFonts(): LibraryFont[] {
  const usedIds = new Set<string>();
  const out: LibraryFont[] = [];

  for (const f of raw.fonts) {
    const category = CATEGORY_MAP[f.category] ?? "Sans-Serif";
    const license = LICENSE_LABELS[f.license] ?? "License information unavailable";
    const free = FREE_LICENSE_ROOTS.has(f.license);
    const id0 = slugify(f.family);
    let id = id0;
    let n = 2;
    while (usedIds.has(id)) id = `${id0}-${n++}`;
    usedIds.add(id);

    const tagPaths = f.tags.map((i) => raw.tags[i] ?? "").filter(Boolean);
    const tagLabels = tagPaths.map(tagLabel);
    const curated = CURATED[id];
    const derived = deriveClassification(
      f.family,
      category,
      f.condensed,
      f.expanded,
      ` ${tagPaths.join(" ").toLowerCase()} `,
    );
    const classification: FontClassification = {
      ...derived,
      ...(curated?.classification ?? {}),
    };

    const traits =
      curated?.traits ??
      tagLabels.slice(0, 4).map((l) => `${l}`);
    const bestFor =
      curated?.bestFor ??
      (tagLabels.length
        ? tagLabels.slice(0, 2).join(", ")
        : `${category} text & display`);
    const designers = f.designers?.length
      ? f.designers.slice(0, 3).join(", ") + (f.designers.length > 3 ? " et al." : "")
      : "Unknown designer";

    const subsets = f.subsets
      .map((i) => raw.subsets[i] ?? "")
      .filter(Boolean);

    const haystack = [
      f.family,
      designers,
      category,
      traits.join(" "),
      bestFor,
      tagLabels.join(" "),
      license,
      free ? "free open source" : "",
      f.variable ? "variable" : "",
      f.condensed ? "condensed narrow" : "",
      f.expanded ? "expanded wide" : "",
      f.italic ? "italic" : "",
    ]
      .join(" ")
      .toLowerCase();

    out.push({
      id,
      family: f.family,
      category,
      kind: "google",
      designers,
      weights: f.weights.length ? f.weights : [400],
      italic: f.italic,
      variable: f.variable,
      subsets,
      license,
      licenseRaw: f.license,
      source: `https://fonts.google.com/specimen/${f.family.replace(/ /g, "+")}`,
      free,
      popularity: f.popularity,
      condensed: f.condensed,
      expanded: f.expanded,
      tagIdx: f.tags,
      tagPaths,
      traits,
      bestFor,
      notes: curated?.notes,
      classification,
      haystack,
    });
  }
  return out;
}

function buildCommercial(): LibraryFont[] {
  return COMMERCIAL_FONTS.map((c) => ({
    id: c.id,
    family: c.family,
    category: c.category,
    kind: "commercial" as const,
    designers: c.designers,
    weights: c.weights,
    italic: true,
    variable: false,
    subsets: c.subsets,
    license: c.license,
    licenseRaw: null,
    source: c.source,
    free: false,
    popularity: 100000 + COMMERCIAL_FONTS.indexOf(c),
    condensed: c.classification.condensed ?? false,
    expanded: c.classification.wide ?? false,
    tagIdx: [],
    tagPaths: [],
    traits: c.traits,
    bestFor: c.bestFor,
    classification: c.classification,
    freeAlternatives: c.freeAlternatives,
    haystack: [
      c.family,
      c.designers,
      c.category,
      c.traits.join(" "),
      c.bestFor,
      c.license,
      "commercial paid premium",
      c.freeAlternatives.join(" "),
    ]
      .join(" ")
      .toLowerCase(),
  }));
}

/** The complete searchable library (Google families first, then paid). */
export const LIBRARY: LibraryFont[] = [...buildGoogleFonts(), ...buildCommercial()];

const byId = new Map<string, LibraryFont>();
const byKey = new Map<string, LibraryFont>();
for (const f of LIBRARY) {
  if (!byId.has(f.id)) byId.set(f.id, f);
  const key = normalizeFamilyKey(f.family);
  if (!byKey.has(key)) byKey.set(key, f);
}

export const LIBRARY_STATS = {
  total: raw.fonts.length + COMMERCIAL_FONTS.length,
  google: raw.fonts.length,
  commercial: COMMERCIAL_FONTS.length,
  tagged: raw.fonts.filter((f) => f.tags.length > 0).length,
  generatedAt: raw.generatedAt,
};

/** Look up by id, family, or PostScript-style key ("OpenSans"). */
export function findLibraryFont(q: string): LibraryFont | undefined {
  const key = String(q ?? "").trim();
  if (!key) return undefined;
  return (
    byId.get(key) ??
    byKey.get(normalizeFamilyKey(key)) ??
    LIBRARY.find((f) => f.family.toLowerCase() === key.toLowerCase())
  );
}

/* ------------------------------------------------------------------ */
/* Back-compat aliases for the Font Finder API surface                 */
/* (consumed by lib/googleFonts and components/FontDetector).          */
/* ------------------------------------------------------------------ */

export type FontEntry = LibraryFont;

/** The full library under its legacy name. */
export const FONTS: LibraryFont[] = LIBRARY;

/** Look up a curated commercial/paid record by id or family name. */
export function findCommercial(q: string): CommercialFontRecord | undefined {
  const key = String(q ?? "").trim().toLowerCase();
  if (!key) return undefined;
  return COMMERCIAL_FONTS.find((c) => c.id === key || c.family.toLowerCase() === key);
}

/** Legacy name for freeAlternativesFor — curated free stand-ins for a paid family. */
export function freeAlternativesForCommercial(
  family: string,
): { commercial: LibraryFont | undefined; free: LibraryFont[] } {
  return freeAlternativesFor(family);
}

/* ------------------------------------------------------------------ */
/* Style filters (real data: official tags + measured flags)           */
/* ------------------------------------------------------------------ */

export interface StyleFilterDef {
  id: string;
  label: string;
  test: (f: LibraryFont) => boolean;
}

const hasAnyTag = (f: LibraryFont, ...idx: number[]): boolean =>
  idx.some((i) => f.tagIdx.includes(i));

/**
 * Tag indices reference googleFontCatalog.json's `tags` table (regenerated
 * by scripts/fetch-font-catalog.mjs — print the table to refresh these).
 */
export const STYLE_FILTERS: StyleFilterDef[] = [
  { id: "geometric", label: "Geometric", test: (f) => f.classification.geometric === true || hasAnyTag(f, 18, 47, 43) },
  { id: "rounded", label: "Rounded", test: (f) => f.classification.rounded === true || hasAnyTag(f, 32, 36) },
  { id: "playful", label: "Playful", test: (f) => hasAnyTag(f, 39, 63, 20, 51, 21) },
  { id: "retro", label: "Retro & Vintage", test: (f) => hasAnyTag(f, 9, 40, 71, 55, 62, 61, 70, 67) },
  { id: "tech", label: "Tech", test: (f) => hasAnyTag(f, 48, 41, 67, 59) },
  { id: "elegant", label: "Elegant", test: (f) => hasAnyTag(f, 30, 31, 69, 29) },
  { id: "editorial", label: "Editorial", test: (f) => f.category === "Serif" || hasAnyTag(f, 3, 38, 54) },
  { id: "minimal", label: "Minimal", test: (f) => hasAnyTag(f, 1, 42, 54, 38) },
  { id: "handwritten", label: "Handwritten", test: (f) => f.category === "Script" || hasAnyTag(f, 49, 50, 25) },
  { id: "bold", label: "Bold", test: (f) => f.weights.some((w) => w >= 700) || (f.classification.weightHint ?? 0) >= 7 },
  { id: "condensed", label: "Condensed", test: (f) => f.condensed },
  { id: "variable", label: "Variable", test: (f) => f.variable },
  { id: "free", label: "Free", test: (f) => f.free },
];

/** Query-language synonyms → haystack terms (style tags live in the hay). */
const QUERY_SYNONYMS: Record<string, string[]> = {
  rounded: ["round", "blobby", "soft"],
  geometric: ["superellipse", "circle", "futura"],
  playful: ["wacky", "cute", "childlike", "happy"],
  retro: ["vintage", "art nouveau", "art deco", "blackletter", "woodtype", "tuscan", "medieval", "pixel", "distressed"],
  tech: ["techno", "futuristic", "pixel", "monospace", "mono"],
  futuristic: ["techno", "futuristic", "pixel"],
  elegant: ["sophisticated", "formal", "didone", "fancy", "script"],
  editorial: ["easy reading", "transitional", "old style", "garalde", "didone", "venetian", "scotch", "grotesque"],
  minimal: ["calm", "stiff", "neo grotesque", "grotesque"],
  handwritten: ["handwritten", "script", "brush", "informal"],
  cursive: ["script", "handwritten", "connected"],
  mono: ["monospace", "mono"],
  monospace: ["mono"],
  bold: ["black", "heavy"],
  condensed: ["narrow"],
  sans: ["sans-serif", "grotesque"],
  serif: ["old style", "didone", "slab"],
  free: ["open source", "open font"],
};

export interface LibraryFilter {
  query?: string;
  categories?: FontCategory[];
  /** STYLE_FILTERS ids — all must match. */
  styles?: string[];
  freeOnly?: boolean;
  commercialOnly?: boolean;
  variableOnly?: boolean;
  sort?: "popular" | "az";
}

function matchesQuery(f: LibraryFont, q: string): boolean {
  if (!q) return true;
  const tokens = q.toLowerCase().split(/\s+/).filter(Boolean);
  return tokens.every((t) => {
    if (f.haystack.includes(t)) return true;
    const syns = QUERY_SYNONYMS[t];
    if (syns && syns.some((s) => f.haystack.includes(s))) return true;
    // tolerate simple plurals
    if (t.endsWith("s") && f.haystack.includes(t.slice(0, -1))) return true;
    if (!t.endsWith("s") && f.haystack.includes(`${t}s`)) return true;
    return false;
  });
}

/** Search + filter the full library. Cheap enough for per-keystroke use. */
export function searchLibrary(filter: LibraryFilter = {}): LibraryFont[] {
  const q = (filter.query ?? "").trim();
  const cats =
    filter.categories && filter.categories.length
      ? new Set(filter.categories)
      : null;
  const styleDefs = (filter.styles ?? [])
    .map((id) => STYLE_FILTERS.find((s) => s.id === id))
    .filter((s): s is StyleFilterDef => !!s);

  const pool = filter.commercialOnly
    ? LIBRARY.filter((f) => f.kind === "commercial")
    : LIBRARY.filter((f) => f.kind === "google");

  const out = pool.filter((f) => {
    if (filter.freeOnly && !f.free) return false;
    if (filter.variableOnly && !f.variable) return false;
    if (cats && !cats.has(f.category)) return false;
    if (styleDefs.length && !styleDefs.every((s) => s.test(f))) return false;
    if (!matchesQuery(f, q)) return false;
    return true;
  });

  if (filter.sort === "az") {
    out.sort((a, b) => a.family.localeCompare(b.family));
  } else if (filter.commercialOnly) {
    // keep declaration order for the small curated paid table
  } else {
    out.sort((a, b) => a.popularity - b.popularity);
  }
  return out;
}

/* ------------------------------------------------------------------ */
/* Alternatives + CSS export                                            */
/* ------------------------------------------------------------------ */

/** Curated free alternatives for a commercial family (resolved, best first). */
export function freeAlternativesFor(
  family: string,
): { commercial: LibraryFont | undefined; free: LibraryFont[] } {
  const comm = findLibraryFont(family);
  if (!comm || comm.kind !== "commercial" || !comm.freeAlternatives) {
    return { commercial: undefined, free: [] };
  }
  const free = comm.freeAlternatives
    .map((name) => findLibraryFont(name))
    .filter((f): f is LibraryFont => !!f && f.free);
  return { commercial: comm, free };
}

/** Google Fonts CSS2 URL for a family + weights. */
export function cssUrlFor(family: string, weights: number[] = [400, 700]): string {
  const fam = family.replace(/ /g, "+");
  const sorted = [...new Set(weights)].sort((a, b) => a - b);
  return sorted.length
    ? `https://fonts.googleapis.com/css2?family=${fam}:wght@${sorted.join(";")}&display=swap`
    : `https://fonts.googleapis.com/css2?family=${fam}&display=swap`;
}

export function cssImportSnippet(
  family: string,
  weights: number[] = [400, 700],
  _category?: FontCategory,
): string {
  return `@import url('${cssUrlFor(family, weights)}');`;
}

export function fontFamilyDecl(
  family: string,
  category?: FontCategory,
): string {
  const fallback =
    category === "Monospace"
      ? "monospace"
      : category === "Serif"
        ? "serif"
        : category === "Script" || category === "Display"
          ? "cursive"
          : "sans-serif";
  return `font-family: '${family}', ${fallback};`;
}

/**
 * Full copyable CSS block for a font. Returns null for paid families —
 * we never fabricate an @import for fonts we cannot legally serve.
 */
export function buildCssSnippet(
  font: LibraryFont,
  weight: number,
  letterSpacing: number,
): string | null {
  if (!font.free) return null;
  const w = font.weights.includes(weight) ? weight : 400;
  // Ship every sane weight but always the one shown in the snippet.
  const urlWeights = font.weights.filter((x) => x <= 700 || x === w);
  if (!urlWeights.includes(w)) urlWeights.push(w);
  return [
    `@import url('${cssUrlFor(font.family, urlWeights)}');`,
    ``,
    `.font-style {`,
    `  ${fontFamilyDecl(font.family, font.category)}`,
    `  font-weight: ${w};`,
    `  letter-spacing: ${letterSpacing}px;`,
    `}`,
  ].join("\n");
}

/** One css2 URL covering several families (used by the compare tray). */
export function cssImportForFonts(fonts: LibraryFont[]): string {
  const usable = fonts.filter((f) => f.free);
  if (!usable.length) return "";
  const params = usable
    .map((f) => {
      const fam = f.family.replace(/ /g, "+");
      const ws = f.weights.filter((x) => x <= 700);
      return ws.length
        ? `family=${fam}:wght@${[...new Set(ws)].sort((a, b) => a - b).join(";")}`
        : `family=${fam}`;
    })
    .join("&");
  return `@import url('https://fonts.googleapis.com/css2?${params}&display=swap');`;
}
